import re
from dataclasses import dataclass, field
from typing import Optional

# Keep a Changelog release heading: ``## [2.4.0] - 2024-05-02`` or ``## [Unreleased]``.
HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?:\s+-\s+(?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)

# An HTML comment, inline or spanning several lines. Non-greedy so that two
# comments on one line are matched separately.
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)

# Placeholder left where a comment was removed, so we can drop the whitespace
# a comment leaves at the end of a line without touching other lines.
_MARK = "\0"


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    """Remove HTML comments and the end-of-line whitespace they leave behind."""
    text = COMMENT.sub(_MARK, text)
    # A removed comment that was the last thing on its line takes the surrounding
    # horizontal whitespace with it.
    text = re.sub(rf"[ \t]*{_MARK}[ \t]*$", "", text, flags=re.MULTILINE)
    # Comments in the middle of a line are simply removed.
    return text.replace(_MARK, "")


def parse_changelog(text):
    releases = []
    current = None
    for line in strip_comments(text).splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match:
                current = Release(match.group("version"), match.group("date"))
                releases.append(current)
            else:
                # Some other second-level heading: not part of any release.
                current = None
        elif current is not None:
            current.body.append(line)
    return releases


def _normalise_body(lines):
    """Collapse runs of blank lines and drop leading/trailing blank lines."""
    out = []
    for line in lines:
        if line.strip() == "":
            if out and out[-1] != "":
                out.append("")
        else:
            out.append(line)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            if release.date:
                heading = f"# {release.version} ({release.date})"
            else:
                heading = f"# {release.version}"
            body = _normalise_body(release.body)
            if not body:
                return f"{heading}\n"
            return f"{heading}\n\n{body}\n"
    raise LookupError(version)

